//! Windows RTL ACL and absolute security-descriptor routines.
//! Supports caller-owned buffers; no kernel-pool allocation is performed.
use super::sid::{SidHeader};
const STATUS_SUCCESS:i32=0;
const STATUS_INVALID_PARAMETER:i32=0xC000000Du32 as i32;
const STATUS_BUFFER_TOO_SMALL:i32=0xC0000023u32 as i32;
const STATUS_INVALID_ACL:i32=0xC0000077u32 as i32;
const STATUS_INVALID_SECURITY_DESCR:i32=0xC0000079u32 as i32;
const ACL_REVISION:u8=2;
const ACL_REVISION_DS:u8=4;
const SE_DACL_PRESENT:u16=0x0004;
const SE_SACL_PRESENT:u16=0x0010;
const SE_DACL_DEFAULTED:u16=0x0008;
const SE_SACL_DEFAULTED:u16=0x0020;
const SE_OWNER_DEFAULTED:u16=0x0001;
const SE_GROUP_DEFAULTED:u16=0x0002;
const SE_SELF_RELATIVE:u16=0x8000;
#[repr(C)] pub struct RtlAcl {pub revision:u8,pub sbz1:u8,pub size:u16,pub ace_count:u16,pub sbz2:u16}
#[repr(C)] pub struct RtlAceHeader {pub ace_type:u8,pub ace_flags:u8,pub ace_size:u16}
#[repr(C)] pub struct RtlSecurityDescriptor {pub revision:u8,pub sbz1:u8,pub control:u16,pub owner:*mut SidHeader,pub group:*mut SidHeader,pub sacl:*mut RtlAcl,pub dacl:*mut RtlAcl}
#[inline] unsafe fn acl_valid(a:*const RtlAcl)->bool {if a.is_null(){return false;}let x=unsafe{&*a};x.revision>=ACL_REVISION&&x.revision<=ACL_REVISION_DS&&x.size>=8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_create_acl(acl:*mut RtlAcl,length:u32,revision:u32)->i32 {
 if acl.is_null()||length<8||length>u16::MAX as u32||!(revision==ACL_REVISION as u32||revision==ACL_REVISION_DS as u32){return STATUS_INVALID_PARAMETER;}
 unsafe{(*acl).revision=revision as u8;(*acl).sbz1=0;(*acl).size=length as u16;(*acl).ace_count=0;(*acl).sbz2=0;}STATUS_SUCCESS
}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_valid_acl(acl:*const RtlAcl)->u8 {if !unsafe{acl_valid(acl)}{return 0;}let a=unsafe{&*acl};let mut off=8usize;for _ in 0..a.ace_count{if off+4>a.size as usize{return 0;}let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||h.ace_size%4!=0||off+h.ace_size as usize>a.size as usize{return 0;}off+=h.ace_size as usize;}1}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_ace(acl:*const RtlAcl,index:u32,out:*mut *mut core::ffi::c_void)->i32 {
 if out.is_null()||!unsafe{acl_valid(acl)}{return STATUS_INVALID_ACL;}let a=unsafe{&*acl};if index>=a.ace_count as u32{return STATUS_INVALID_PARAMETER;}let mut off=8usize;for _ in 0..index{let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return STATUS_INVALID_ACL;}off+=h.ace_size as usize;}if off+4>a.size as usize{return STATUS_INVALID_ACL;}unsafe{*out=(acl as *mut u8).add(off) as *mut core::ffi::c_void;}STATUS_SUCCESS
}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_first_free_ace(acl:*const RtlAcl,out:*mut *mut core::ffi::c_void)->u8 {
 if out.is_null()||!unsafe{acl_valid(acl)}{return 0;}let a=unsafe{&*acl};let mut off=8usize;for _ in 0..a.ace_count{if off+4>a.size as usize{return 0;}let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return 0;}off+=h.ace_size as usize;}unsafe{*out=(acl as *mut u8).add(off) as *mut core::ffi::c_void;}1
}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_delete_ace(acl:*mut RtlAcl,index:u32)->i32 {
 if !unsafe{acl_valid(acl)}{return STATUS_INVALID_ACL;}let a=unsafe{&mut *acl};if index>=a.ace_count as u32{return STATUS_INVALID_PARAMETER;}let mut off=8usize;for _ in 0..index{let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};off+=h.ace_size as usize;}let len=unsafe{(*(acl as *const u8).add(off) as u8)};let size=unsafe{*((acl as *const u8).add(off+2) as *const u16)} as usize;if size<4||off+size>a.size as usize{return STATUS_INVALID_ACL;}let end=off+size;let total=a.size as usize-end;unsafe{core::ptr::copy((acl as *const u8).add(end),(acl as *mut u8).add(off),total);}a.ace_count-=1;let _=len;STATUS_SUCCESS
}
unsafe fn add_basic_ace(acl:*mut RtlAcl,revision:u32,flags:u32,mask:u32,sid:*const SidHeader,ace_type:u8)->i32 {
 if !unsafe{acl_valid(acl)}||sid.is_null(){return STATUS_INVALID_PARAMETER;}let a=unsafe{&mut *acl};if revision!=ACL_REVISION as u32&&revision!=ACL_REVISION_DS as u32{return STATUS_INVALID_PARAMETER;}let sid_len=unsafe{super::sid::rtl_length_sid(sid)} as usize;if sid_len==0{return STATUS_INVALID_PARAMETER;}let ace_size=8usize.saturating_add(sid_len);let ace_size=(ace_size+3)&!3;let mut off=8usize;for _ in 0..a.ace_count{if off+4>a.size as usize{return STATUS_INVALID_ACL;}let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return STATUS_INVALID_ACL;}off+=h.ace_size as usize;}if off+ace_size>a.size as usize||ace_size>u16::MAX as usize{return STATUS_BUFFER_TOO_SMALL;}unsafe{let p=(acl as *mut u8).add(off);*(p as *mut RtlAceHeader)=RtlAceHeader{ace_type,ace_flags:flags as u8,ace_size:ace_size as u16};*((p.add(4)) as *mut u32)=mask;core::ptr::copy(sid as *const u8,p.add(8),sid_len);if ace_size>8+sid_len{core::ptr::write_bytes(p.add(8+sid_len),0,ace_size-8-sid_len);} }a.ace_count+=1;STATUS_SUCCESS
}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_access_allowed_ace(acl:*mut RtlAcl,revision:u32,mask:u32,sid:*const SidHeader)->i32{unsafe{add_basic_ace(acl,revision,0,mask,sid,0)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_access_allowed_ace_ex(acl:*mut RtlAcl,revision:u32,flags:u32,mask:u32,sid:*const SidHeader)->i32{unsafe{add_basic_ace(acl,revision,flags,mask,sid,0)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_access_denied_ace_ex(acl:*mut RtlAcl,revision:u32,flags:u32,mask:u32,sid:*const SidHeader)->i32{unsafe{add_basic_ace(acl,revision,flags,mask,sid,1)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_create_security_descriptor(sd:*mut RtlSecurityDescriptor,revision:u32)->i32 {
 if sd.is_null()||revision!=1{return STATUS_INVALID_PARAMETER;}unsafe{(*sd).revision=revision as u8;(*sd).sbz1=0;(*sd).control=0;(*sd).owner=core::ptr::null_mut();(*sd).group=core::ptr::null_mut();(*sd).sacl=core::ptr::null_mut();(*sd).dacl=core::ptr::null_mut();}STATUS_SUCCESS
}
#[inline] unsafe fn sd_valid(sd:*const RtlSecurityDescriptor)->bool{!sd.is_null()&&unsafe{(*sd).revision==1&&((*sd).control&SE_SELF_RELATIVE)==0}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_valid_security_descriptor(sd:*const RtlSecurityDescriptor)->u8 {if !unsafe{sd_valid(sd)}{return 0;}let s=unsafe{&*sd};if !s.owner.is_null()&&unsafe{super::sid::rtl_valid_sid(s.owner)}==0{return 0;}if !s.group.is_null()&&unsafe{super::sid::rtl_valid_sid(s.group)}==0{return 0;}if (s.control&SE_DACL_PRESENT)!=0&&!s.dacl.is_null()&&unsafe{rtl_valid_acl(s.dacl)}==0{return 0;}if (s.control&SE_SACL_PRESENT)!=0&&!s.sacl.is_null()&&unsafe{rtl_valid_acl(s.sacl)}==0{return 0;}1}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_length_security_descriptor(sd:*const RtlSecurityDescriptor)->u32 {if unsafe{sd_valid(sd)}{core::mem::size_of::<RtlSecurityDescriptor>() as u32}else{0}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_control_security_descriptor(sd:*const RtlSecurityDescriptor,control:*mut u16,revision:*mut u32)->i32 {if !unsafe{sd_valid(sd)}||control.is_null()||revision.is_null(){return STATUS_INVALID_SECURITY_DESCR;}unsafe{*control=(*sd).control;*revision=(*sd).revision as u32;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_dacl_security_descriptor(sd:*const RtlSecurityDescriptor,present:*mut u8,dacl:*mut *mut RtlAcl,defaulted:*mut u8)->i32 {if !unsafe{sd_valid(sd)}||present.is_null()||dacl.is_null()||defaulted.is_null(){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&*sd};unsafe{*present=((s.control&SE_DACL_PRESENT)!=0) as u8;*dacl=s.dacl;*defaulted=((s.control&SE_DACL_DEFAULTED)!=0) as u8;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_sacl_security_descriptor(sd:*const RtlSecurityDescriptor,present:*mut u8,sacl:*mut *mut RtlAcl,defaulted:*mut u8)->i32 {if !unsafe{sd_valid(sd)}||present.is_null()||sacl.is_null()||defaulted.is_null(){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&*sd};unsafe{*present=((s.control&SE_SACL_PRESENT)!=0) as u8;*sacl=s.sacl;*defaulted=((s.control&SE_SACL_DEFAULTED)!=0) as u8;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_owner_security_descriptor(sd:*const RtlSecurityDescriptor,owner:*mut *mut SidHeader,defaulted:*mut u8)->i32 {if !unsafe{sd_valid(sd)}||owner.is_null()||defaulted.is_null(){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&*sd};unsafe{*owner=s.owner;*defaulted=((s.control&SE_OWNER_DEFAULTED)!=0) as u8;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_group_security_descriptor(sd:*const RtlSecurityDescriptor,group:*mut *mut SidHeader,defaulted:*mut u8)->i32 {if !unsafe{sd_valid(sd)}||group.is_null()||defaulted.is_null(){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&*sd};unsafe{*group=s.group;*defaulted=((s.control&SE_GROUP_DEFAULTED)!=0) as u8;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_dacl_security_descriptor(sd:*mut RtlSecurityDescriptor,present:u8,dacl:*mut RtlAcl,defaulted:u8)->i32 {if !unsafe{sd_valid(sd)}||(present!=0&&!dacl.is_null()&&unsafe{rtl_valid_acl(dacl)}==0){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&mut *sd};if present!=0{s.control|=SE_DACL_PRESENT;s.dacl=dacl;}else{s.control&=!SE_DACL_PRESENT;s.dacl=core::ptr::null_mut();}if defaulted!=0{s.control|=SE_DACL_DEFAULTED;}else{s.control&=!SE_DACL_DEFAULTED;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_sacl_security_descriptor(sd:*mut RtlSecurityDescriptor,present:u8,sacl:*mut RtlAcl,defaulted:u8)->i32 {if !unsafe{sd_valid(sd)}||(present!=0&&!sacl.is_null()&&unsafe{rtl_valid_acl(sacl)}==0){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&mut *sd};if present!=0{s.control|=SE_SACL_PRESENT;s.sacl=sacl;}else{s.control&=!SE_SACL_PRESENT;s.sacl=core::ptr::null_mut();}if defaulted!=0{s.control|=SE_SACL_DEFAULTED;}else{s.control&=!SE_SACL_DEFAULTED;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_owner_security_descriptor(sd:*mut RtlSecurityDescriptor,owner:*mut SidHeader,defaulted:u8)->i32 {if !unsafe{sd_valid(sd)}||(!owner.is_null()&&unsafe{super::sid::rtl_valid_sid(owner)}==0){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&mut *sd};s.owner=owner;if defaulted!=0{s.control|=SE_OWNER_DEFAULTED;}else{s.control&=!SE_OWNER_DEFAULTED;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_group_security_descriptor(sd:*mut RtlSecurityDescriptor,group:*mut SidHeader,defaulted:u8)->i32 {if !unsafe{sd_valid(sd)}||(!group.is_null()&&unsafe{super::sid::rtl_valid_sid(group)}==0){return STATUS_INVALID_SECURITY_DESCR;}let s=unsafe{&mut *sd};s.group=group;if defaulted!=0{s.control|=SE_GROUP_DEFAULTED;}else{s.control&=!SE_GROUP_DEFAULTED;}STATUS_SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_owner_aces_present(acl:*const RtlAcl)->u8 {if !unsafe{acl_valid(acl)}{return 0;}let a=unsafe{&*acl};let mut off=8usize;for _ in 0..a.ace_count{let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_type==5||h.ace_type==6{return 1;}if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return 0;}off+=h.ace_size as usize;}0}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_aces_buffer_size(acl:*const RtlAcl,out:*mut u32)->i32 {if acl.is_null()||out.is_null(){return STATUS_INVALID_PARAMETER;}if !unsafe{acl_valid(acl)}{return STATUS_INVALID_ACL;}let a=unsafe{&*acl};let mut off=8usize;let mut total=0u32;for _ in 0..a.ace_count{if off+4>a.size as usize{return STATUS_INVALID_ACL;}let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return STATUS_INVALID_ACL;}total=total.saturating_add(h.ace_size as u32);off+=h.ace_size as usize;}unsafe{*out=total;}STATUS_SUCCESS}
